你可以使用 JavaScript 的内置函数 `Math.max()` 和 `Math.min()` 来找到数组中的最大值和最小值。以下是一个简单的脚本：

```javascript
function findMinMax(arr) {
  if (arr.length === 0) {
    return "数组为空";
  }

  let min = arr[0];
  let max = arr[0];

  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < min) {
      min = arr[i];
    } else if (arr[i] > max) {
      max = arr[i];
    }
  }

  return {
    min: min,
    max: max
  };
}

// 示例使用
const array = [1, 2, 3, 4, 5];
const result = findMinMax(array);
console.log(result); // { min: 1, max: 5 }
```

