```python
def generate_fibonacci(n):
    if n <= 0:
        return tuple()
    elif n == 1:
        return (0,)
    elif n == 2:
        return (0, 1)
    else:
        fib_sequence = (0, 1)
        for _ in range(2, n):
            next_value = fib_sequence[-1] + fib_sequence[-2]
            fib_sequence += (next_value,)
        return fib_sequence

fibonacci_tuple = generate_fibonacci(20)
print(fibonacci_tuple)
```

